-- ================================================================
-- VERIFICATION QUERIES
-- ================================================================

-- Count customers
SELECT COUNT(*) as customer_count FROM CDCUSP_CDCUSP
WHERE CUSTID >= 100001 AND CUSTID < 105001;

-- Count accounts
SELECT COUNT(*) as account_count FROM CDACTP_CDACTP
WHERE ACCTNUM >= 400000000001 AND ACCTNUM < 400000010001;

-- Count cards
SELECT COUNT(*) as card_count FROM CDCCMP_CDCCMP
WHERE CARDNUM >= 4111111111111001 AND CARDNUM < 4111111111121001;

-- Account distribution by group
SELECT ACCTGRP, COUNT(*) as count, AVG(CREDLIMIT) as avg_credit_limit
FROM CDACTP_CDACTP
WHERE ACCTNUM >= 400000000001 AND ACCTNUM < 400000010001
GROUP BY ACCTGRP
ORDER BY ACCTGRP;

-- Customer state distribution
SELECT STATE, COUNT(*) as count
FROM CDCUSP_CDCUSP
WHERE CUSTID >= 100001 AND CUSTID < 105001
GROUP BY STATE
ORDER BY count DESC;

